<script setup>
import {ref,computed,onMounted,onUnmounted} from 'vue';
import {snapMove,liveMover} from './window-drag.js';
const windows=ref([]),screens=ref([]),chosen=ref([]),screen=ref(''),busy=ref(false),error=ref(''),message=ref(''),draft=ref({}),area=ref(null),available=ref({w:1000,h:600});
const unified=ref({new_row:true});
const history=ref(null);let alive=true;
const groupVisible=ref(false);let groupTimer;
const count=ref(1),delay=ref(1),regular=ref({active:false,done:0,total:0,results:[]});let timer,observer,request=0;
const settings=ref({width:960,height:540,columns:3,gap:0,padding:0,aspect:true,mode:'网格排列'});
try{Object.assign(settings.value,JSON.parse(localStorage.getItem('running-window-settings')||'{}'))}catch{}
const selected=computed(()=>windows.value.filter(w=>chosen.value.includes(w.id))),changed=computed(()=>windows.value.filter(w=>draft.value[w.id]));
const world=computed(()=>{const rects=screens.value.map(s=>s.work);if(!rects.length)return [0,0,1920,1080];const x=Math.min(...rects.map(r=>r[0])),y=Math.min(...rects.map(r=>r[1]));return [x,y,Math.max(...rects.map(r=>r[0]+r[2]))-x,Math.max(...rects.map(r=>r[1]+r[3]))-y]});
const scale=computed(()=>Math.max(.01,Math.min(available.value.w/world.value[2],available.value.h/world.value[3])));
const stageStyle=computed(()=>({width:world.value[2]*scale.value+'px',height:world.value[3]*scale.value+'px'}));
function rect(w){return draft.value[w.id]||w.rect}
function rectStyle(r){return {left:(r[0]-world.value[0])*scale.value+'px',top:(r[1]-world.value[1])*scale.value+'px',width:r[2]*scale.value+'px',height:r[3]*scale.value+'px'}}
async function call(action,p={}){const r=await window.pywebview.api.running_windows(action,p);if(!r.ok)throw Error(r.error);return r.data}
async function groups(action){try{const r=await window.pywebview.api.group_frames(action);if(!r.ok)throw Error(r.error);groupVisible.value=r.data.visible;if(action!=='status')message.value=groupVisible.value?'分组框已显示，拖动方案名可整组移动；结束整理后隐藏。':'分组框已隐藏';}catch(e){if(action!=='status')error.value=e.message}}
async function unifiedCall(action,p={}){const r=await window.pywebview.api.scheme_layout(action,p);if(!r.ok)throw Error(r.error);return r.data}
async function unifiedStatus(initial=false){try{const r=await unifiedCall('status');unified.value=r.settings;if(initial&&settings.value.mode==='按方案排列'){for(const k of ['width','height','columns','gap','padding','aspect'])settings.value[k]=r.settings[k];}if(r.warning)error.value=r.warning}catch{}}
function unifiedOptions(){return {aspect:settings.value.aspect,screen:screen.value,width:settings.value.width,height:settings.value.height,columns:settings.value.columns,gap:settings.value.gap,padding:settings.value.padding,new_row:unified.value.new_row}}
async function saveUnified(){try{const r=await unifiedCall('settings',unifiedOptions());unified.value=r.settings;message.value='按方案排列设置已保存'}catch(e){error.value=e.message}}
async function arrangeGroups(){if(busy.value||!windows.value.length)return;busy.value=true;error.value='';try{const settings=unifiedOptions(),preview=await unifiedCall('preview',{settings});if(preview.shrink&&!confirm('当前屏幕空间不足，是否缩小窗口后整理？取消后可选择另一块屏幕。'))return;history.value={windows:preview.windows,rects:Object.fromEntries(preview.windows.map(w=>[w.id,[...w.rect]]))};const r=await unifiedCall('apply',{settings,allow_shrink:preview.shrink});const failed=r.results.filter(x=>!x.ok);if(failed.length)error.value=failed.map(x=>x.error).join('；');message.value='已按方案顺序和成员顺序整理 '+(r.results.length-failed.length)+' 个窗口';}catch(e){error.value=e.message}finally{busy.value=false}const problem=error.value;await refresh();if(problem)error.value=problem}
async function refresh(){if(busy.value)return;busy.value=true;error.value='';try{const r=await call('list');windows.value=r.windows;screens.value=r.screens;const ids=new Set(windows.value.map(w=>w.id));chosen.value=chosen.value.filter(id=>ids.has(id));draft.value=Object.fromEntries(Object.entries(draft.value).filter(([id])=>ids.has(id)));if(!screens.value.some(s=>s.id===screen.value))screen.value=screens.value[0]?.id||'';}catch(e){error.value=e.message}finally{busy.value=false}}
async function regularCall(action,p={}){try{const r=await window.pywebview.api.regular_launch(action,p);if(!r.ok)throw Error(r.error);const was=regular.value.active;regular.value=r.data;if(r.data.active){timer??=setInterval(()=>regularCall('status'),1000)}else{clearInterval(timer);timer=null;if(was){await refresh();message.value=r.data.stopped?'已停止后续启动':'启动已提交，窗口加载后点击刷新。';const failures=r.data.results.filter(x=>!x.ok);if(failures.length)error.value=failures.map(x=>x.error).join('；')}}}catch(e){error.value=e.message;clearInterval(timer);timer=null}}
async function arrange(){if(settings.value.mode==='按方案排列')return arrangeGroups();if(busy.value||!selected.value.length)return;busy.value=true;error.value='';const targets=[...selected.value];history.value={windows:targets,rects:Object.fromEntries(targets.map(w=>[w.id,[...w.rect]]))};try{const r=await call('preview',{windows:targets,screen:screen.value,settings:settings.value});Object.assign(draft.value,r.rects);const placed=await call('place',{windows:targets,rects:r.rects,stack:['错落排列','反向错落'].includes(settings.value.mode)});const failed=placed.results.filter(x=>!x.ok);if(failed.length)error.value=failed.map(x=>x.error).join('；');localStorage.setItem('running-window-settings',JSON.stringify(settings.value));message.value='已排列真实窗口，可还原上次调整。'}catch(e){error.value=e.message}finally{draft.value={};busy.value=false}const problem=error.value;await refresh();if(problem)error.value=problem}
async function focus(w){if(!w)return;try{await call('focus',{windows:[w]})}catch(e){error.value=e.message}}
async function closeWindows(targets,all=false){if(busy.value||!targets.length)return;busy.value=true;error.value='';let r;try{r=await call('close',{windows:targets,stop_regular:all})}catch(e){error.value=e.message}finally{busy.value=false}if(r){await refresh();const failed=r.results.filter(x=>!x.ok);message.value=`已关闭 ${r.results.length-failed.length} 个窗口`;if(failed.length)error.value=failed.map(x=>x.error).join('；');if(all)await regularCall('status')}}
function all(){chosen.value=chosen.value.length===windows.value.length?[]:windows.value.map(w=>w.id)}
let drag;
const mover=liveMover(job=>call('place',job),r=>{const failed=r.results.filter(x=>!x.ok);if(failed.length)throw Error(failed.map(x=>x.error).join('；'))},e=>{if(alive){error.value=e.message;message.value='移动未完成，请刷新窗口后重试。'}});
function press(e,w){if(busy.value||e.button!==0)return;if(e.ctrlKey||e.metaKey){chosen.value=chosen.value.includes(w.id)?chosen.value.filter(id=>id!==w.id):[...chosen.value,w.id];return}if(!chosen.value.includes(w.id))chosen.value=[w.id];mover.reset();drag={x:e.clientX,y:e.clientY,targets:[...selected.value],starts:Object.fromEntries(selected.value.map(w=>[w.id,[...rect(w)]])),moved:false};e.currentTarget.setPointerCapture(e.pointerId)}
function move(e){if(!drag)return;const raw=[(e.clientX-drag.x)/scale.value,(e.clientY-drag.y)/scale.value];if(Math.abs(e.clientX-drag.x)+Math.abs(e.clientY-drag.y)<4&&!drag.moved)return;if(!drag.moved){history.value={windows:drag.targets,rects:structuredClone(drag.starts)};busy.value=true}drag.moved=true;const obstacles=windows.value.filter(w=>!drag.starts[w.id]).map(w=>rect(w));const [dx,dy]=snapMove(drag.starts,raw,obstacles,screens.value.map(s=>s.work),Math.min(32,8/scale.value),e.altKey);const rects=Object.fromEntries(Object.entries(drag.starts).map(([id,r])=>[id,[r[0]+dx,r[1]+dy,r[2],r[3]]]));Object.assign(draft.value,rects);message.value=e.altKey?'正在实时移动 · 已临时取消吸附':'正在实时移动 · 靠近窗口自动吸附';mover.push({windows:drag.targets,rects})}
async function release(){if(!drag)return;const moved=drag.moved;drag=null;if(!moved)return;await mover.flush();if(!alive)return;draft.value={};busy.value=false;const problem=error.value;await refresh();if(problem)error.value=problem;else message.value='窗口位置已实时更新 · 可还原上次调整'}
async function undo(){if(busy.value||!history.value)return;busy.value=true;error.value='';try{const r=await call('place',history.value);const failed=r.results.filter(x=>!x.ok);if(failed.length)throw Error(failed.map(x=>x.error).join('；'));history.value=null;message.value='已还原上次调整前的位置'}catch(e){error.value=e.message}finally{busy.value=false}const problem=error.value;await refresh();if(problem)error.value=problem}
onMounted(async()=>{observer=new ResizeObserver(([entry])=>{available.value={w:Math.max(100,entry.contentRect.width-64),h:Math.max(100,entry.contentRect.height-64)}});if(area.value)observer.observe(area.value);await refresh();await regularCall('status');await groups('status');await unifiedStatus(true);if(unified.value.screen&&screens.value.some(s=>s.id===unified.value.screen))screen.value=unified.value.screen;groupTimer=setInterval(()=>{groups('status');unifiedStatus()},1000)});
onUnmounted(()=>{alive=false;mover.flush();observer?.disconnect();clearInterval(timer);clearInterval(groupTimer)});
</script>
<template><section class="window-canvas-page"><header><div><h1>运行窗口 <span>{{windows.length}} 个</span></h1><p>拖动实时移动 · 靠近边缘吸附 · Alt 临时取消吸附</p></div><button @click="refresh" :disabled="busy">↻ 刷新窗口</button></header><nav class="canvas-toolbar" aria-label="窗口工具栏"><div class="tool-group launch-tool"><label>数量<input aria-label="常规启动数量" type="number" min="1" max="20" v-model.number="count" :disabled="regular.active"></label><label>间隔<input aria-label="常规启动间隔" type="number" min="0" max="60" step="0.5" v-model.number="delay" :disabled="regular.active"><small>秒</small></label><button class="primary-tool" @click="regularCall('start',{count,delay})" :disabled="regular.active||busy">{{regular.active?regular.done+' / '+regular.total:'打开游戏'}}</button><button v-if="regular.active" @click="regularCall('stop')">停止</button></div><div class="tool-group"><button @click="all" :disabled="busy||!windows.length">{{windows.length&&chosen.length===windows.length?'取消全选':'全选'}}</button><button @click="focus(selected[0])" :disabled="busy||selected.length!==1">定位</button><button class="close-tool" @click="closeWindows(selected)" :disabled="busy||!selected.length" title="直接结束选中的游戏">关闭所选</button><details class="tool-menu"><summary>更多 ▾</summary><div class="menu-panel"><button class="close-tool" @click="closeWindows(windows,true);$event.currentTarget.closest('details').open=false" :disabled="busy||!windows.length">关闭全部 {{windows.length}} 个窗口</button><p>包含其他启动来源，停止后续启动任务。</p></div></details></div><div class="tool-group arrange-tool"><select aria-label="目标屏幕" v-model="screen"><option v-for="(s,i) in screens" :key="s.id" :value="s.id">屏幕 {{i+1}}{{s.primary?' · 主屏':''}}</option></select><button @click="groups(groupVisible?'hide':'show')" :disabled="busy||!windows.length">{{groupVisible?'隐藏分组框':'显示分组框'}}</button><button @click="arrange" :disabled="busy||(settings.mode==='按方案排列'?!windows.length:!selected.length)">排列窗口</button><details class="tool-menu"><summary>排列设置 ▾</summary><div class="settings-popover"><h3>排列设置</h3><label>方式<select v-model="settings.mode"><option>网格排列</option><option>错落排列</option><option>反向错落</option><option>按方案排列</option></select></label><label>列数<input type="number" v-model.number="settings.columns" min="1"></label><label>画面宽度<input type="number" v-model.number="settings.width" @change="settings.aspect&&(settings.height=Math.round(settings.width*9/16))"></label><label>画面高度<input type="number" v-model.number="settings.height" :disabled="settings.aspect"></label><label>间距<input type="number" v-model.number="settings.gap" min="0"></label><label>留白<input type="number" v-model.number="settings.padding" min="0"></label><label class="aspect-check"><input type="checkbox" v-model="unified.new_row" @change="saveUnified">每个方案另起一行</label><button @click="saveUnified">保存统一排列设置</button><label class="aspect-check"><input type="checkbox" v-model="settings.aspect" @change="settings.aspect&&(settings.height=Math.round(settings.width*9/16))">锁定16:9</label><p>直接排列所选真实窗口。错落排列从屏幕中部偏左上展开；反向错落从左下向右上层叠。</p></div></details></div></nav><div class="scheme-layout-tools"><button @click="arrangeGroups" :disabled="busy||!windows.length">按方案整理全部</button><span>方案顺序 → 成员顺序 · 同一窗口只占一次</span></div><div class="canvas-feedback"><span :class="{error}" role="status">{{error||message||'拖动即移动真实窗口，Ctrl 多选；靠近窗口吸附，Alt 临时取消。'}}</span><small>已选 {{selected.length}} 个 · {{changed.length?'正在移动 '+changed.length+' 个窗口':'与实际位置一致'}}</small></div><div class="desktop-canvas" ref="area" @pointerdown.self="chosen=[]"><div class="desktop-stage" :style="stageStyle"><div v-for="(s,i) in screens" :key="s.id" class="monitor-region" :style="rectStyle(s.work)"><span>屏幕 {{i+1}} · {{s.work[2]}} × {{s.work[3]}}</span></div><div v-for="(w,i) in windows" :key="w.id" class="canvas-window" :class="{selected:chosen.includes(w.id),modified:!!draft[w.id]}" :style="{...rectStyle(rect(w)),'--plan-color':w.plan_color||'#a69880',zIndex:chosen.includes(w.id)?20+i:2+i}" @pointerdown="press($event,w)" @pointermove="move" @pointerup="release" @pointercancel="release" @dblclick="focus(w)" :title="(w.plan?w.plan+' · ':'')+w.title+' · 双击定位'"><div class="window-caption"><b>{{i+1}}</b><strong>{{w.title}}</strong></div><div class="window-surface"><span>{{w.title}}</span><small>{{w.plan||'未归入方案'}}</small><small>{{rect(w)[2]}} × {{rect(w)[3]}}</small></div></div></div><div v-if="!windows.length&&!busy" class="canvas-empty"><span>▦</span><h2>还没有打开的游戏窗口</h2><p>在上方选择数量，点击“打开游戏”。<br>原版常规启动不绑定角色，登录由你在游戏内完成。</p></div></div><footer><span>常规启动共用原游戏缓存 · 关闭直接结束游戏进程</span><div><button @click="undo" :disabled="busy||!history">还原上次调整</button></div></footer></section></template>
<style scoped>
.scheme-layout-tools{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.scheme-layout-tools span{font-size:11px;color:#8c7965}

.window-canvas-page{height:100%;min-height:0;padding:22px;box-sizing:border-box;display:flex;flex-direction:column;gap:12px;color:#3d352b}.window-canvas-page header{display:flex;justify-content:space-between;align-items:center}.window-canvas-page h1{font-size:23px;margin:0}.window-canvas-page h1 span{font-size:13px;font-weight:400;color:#88755f;margin-left:8px}.window-canvas-page header p{font-size:12px;margin:6px 0 0;color:#8c7965}.window-canvas-page button,.window-canvas-page select,.window-canvas-page input{font:inherit;border:1px solid #ddcfbc;border-radius:5px;background:#fffcf7;color:#5e4b37;padding:7px 10px;box-sizing:border-box}.window-canvas-page button{cursor:pointer;white-space:nowrap}.window-canvas-page button:disabled{opacity:.42;cursor:default}.window-canvas-page .primary-tool{background:#785b40;color:#fff8ed;border-color:#785b40}.canvas-toolbar{display:flex;flex-wrap:wrap;gap:10px;background:#fffcf7;border:1px solid #e1d4c3;border-radius:9px;padding:10px 12px;align-items:center;flex-shrink:0}.tool-group{display:flex;align-items:center;gap:7px;padding-right:12px;border-right:1px solid #e5dacc}.tool-group:last-child{border:0;padding-right:0}.tool-group label{display:flex;align-items:center;gap:6px;font-size:12px;color:#8a745c}.tool-group input{width:55px;padding:7px 4px}.launch-tool small{margin-left:-3px}.window-canvas-page .close-tool{color:#9a5341}.arrange-tool{margin-left:auto}.tool-menu{position:relative}.tool-menu summary{cursor:pointer;color:#78634d;font-size:13px;list-style:none;padding:8px 5px;white-space:nowrap}.menu-panel,.settings-popover{position:absolute;right:0;top:100%;z-index:100;background:#fffcf7;border:1px solid #d9cbb7;border-radius:8px;padding:16px;box-shadow:0 8px 30px #3a2b1726}.menu-panel{width:250px}.menu-panel p,.settings-popover p{font-size:12px;color:#937e67;line-height:1.5;margin:12px 0 0}.settings-popover{width:330px;display:grid;grid-template-columns:1fr 1fr;gap:12px}.settings-popover h3{grid-column:span 2;margin:0;font-size:16px}.settings-popover label{display:flex;flex-direction:column;align-items:stretch;gap:5px}.settings-popover input,.settings-popover select{width:100%}.settings-popover .aspect-check{flex-direction:row;align-items:center;grid-column:span 2}.aspect-check input{width:auto}.settings-popover p{grid-column:span 2}.canvas-feedback{display:flex;justify-content:space-between;gap:10px;font-size:12px;color:#8a7965;min-height:20px}.canvas-feedback .error{color:#a44b38}.canvas-feedback small{white-space:nowrap}.desktop-canvas{position:relative;flex:1;min-height:200px;background:#eee9df;border:1px solid #ddd1c1;border-radius:10px;display:flex;align-items:center;justify-content:center;overflow:hidden;background-image:radial-gradient(#c4bba947 1px,transparent 1px);background-size:18px 18px}.desktop-stage{position:relative;flex-shrink:0}.monitor-region{position:absolute;border:1px solid #a3947c;background:#25312fe8;box-sizing:border-box;border-radius:5px;box-shadow:0 8px 20px #30271615}.monitor-region>span{position:absolute;bottom:8px;left:12px;color:#aab7ad;font-size:11px}.canvas-window{position:absolute;border:1px solid var(--plan-color,#a69880);border-left-width:3px;box-sizing:border-box;overflow:hidden;border-radius:4px;background:#ecdfcb;box-shadow:0 2px 6px #151a1740;cursor:grab;user-select:none;touch-action:none}.canvas-window.selected{outline:2px solid #c29459;outline-offset:1px}.canvas-window.modified{border-color:#ba8244}.window-caption{display:flex;align-items:center;gap:6px;background:#fbf6ed;border-bottom:1px solid #cdbca3;padding:5px 7px;color:#67533b;font-size:11px;white-space:nowrap}.window-caption b{background:#c9b291;color:#fffaf3;border-radius:3px;padding:1px 4px}.window-caption strong{overflow:hidden;text-overflow:ellipsis;font-weight:500}.window-surface{height:calc(100% - 30px);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:7px;color:#9a8262;font-size:12px;overflow:hidden}.window-surface span{max-width:90%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.window-surface small{font-size:10px;opacity:.7}.canvas-empty{position:absolute;inset:0;display:flex;flex-direction:column;justify-content:center;align-items:center;background:#f4efe6dc;text-align:center;pointer-events:none}.canvas-empty>span{font-size:42px;color:#b09a7f}.canvas-empty h2{font-size:17px;color:#705d46;margin:12px 0 6px}.canvas-empty p{font-size:13px;color:#93816b;line-height:1.8}.window-canvas-page footer{display:flex;align-items:center;justify-content:space-between;font-size:11px;color:#99856e;gap:12px}.window-canvas-page footer>div{display:flex;gap:10px}.window-canvas-page footer .primary-tool{min-width:130px}@media(max-width:1250px){.window-canvas-page{padding:16px}.arrange-tool{margin-left:0}.canvas-toolbar{gap:8px}.tool-group{padding-right:8px}.canvas-feedback{flex-wrap:wrap}}
</style>
